// Convert Polygon2d to CGAL polygon
internal::Polygon_2 cgalP1, cgalP2;
for (const cg3::Point2d& p : P1.vectorPoints()) {
    cgalP1.push_back(internal::Point_2(p.x(), p.y()));
}
for (const cg3::Point2d& p : P2.vectorPoints()) {
    cgalP2.push_back(internal::Point_2(p.x(), p.y()));
}

// Compute difference
internal::Pwh_list_2 result;
CGAL::difference(cgalP1, cgalP2, std::back_inserter(result));

// Convert result back to PolygonWithHoles2d
std::vector<PolygonWithHoles2d> output;
for (const internal::Polygon_with_holes_2& pwh : result) {
    PolygonWithHoles2d polyWithHoles;

    // Convert outer boundary
    const internal::Polygon_2& outer = pwh.outer_boundary();
    std::vector<cg3::Point2d> outerPoints;
    for (internal::Polygon_2::Vertex_const_iterator vit = outer.vertices_begin(); vit != outer.vertices_end(); ++vit) {
        double x, y;
        internal::getCoordinates(*vit, x, y);
        outerPoints.emplace_back(x, y);
    }
    polyWithHoles.setOuterBoundary(outerPoints);

    // Convert holes
    for (internal::Polygon_with_holes_2::Hole_const_iterator hit = pwh.holes_begin(); hit != pwh.holes_end(); ++hit) {
        std::vector<cg3::Point2d> holePoints;
        for (internal::Polygon_2::Vertex_const_iterator vit = hit->vertices_begin(); vit != hit->vertices_end(); ++vit) {
            double x, y;
            internal::getCoordinates(*vit, x, y);
            holePoints.emplace_back(x, y);
        }
        polyWithHoles.addHole(holePoints);
    }

    output.push_back(std::move(polyWithHoles));
}

return output;

